window.kbPageData["views/entry/k-8b7425ce10958bbe"] = {"key":"entry/k-8b7425ce10958bbe","state":{"route":"entry/k-8b7425ce10958bbe"},"node":{"id":"k-8b7425ce10958bbe","mode":"k","title":"必要条件与逆否推理","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["必要条件命题的蕴含方向与逆否等价"],"qs":["江苏 2024 A类 行测#91"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"如果甲是乙成立的必要条件，那么乙成立必有甲成立。等价地，甲不成立时，乙也不成立。","review":{"definition":"如果甲是乙成立的必要条件，那么乙成立必有甲成立。等价地，甲不成立时，乙也不成立。","explanation":"题干的“除非……否则不能”把两翼健壮且能合力推动身体设为飞向天空的必要条件。②从能飞推出两项条件都满足，③从至少一项条件不满足推出不能飞，所以选B。①把两项条件都满足当成能飞的充分条件，④从不能飞倒推至少一项条件不满足，题干都推不出。","references":[],"evidence":"除非两翼健壮并以共同的力量来推动身体，否则它不能飞向天空","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#91":{"paper":"江苏 2024 A类 行测","n":91,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",19],"asrc":["0126a1c8aceee632ea2b.pdf",28],"card":"cc4148c851bb8b496f360009","links":[{"id":"k-8b7425ce10958bbe","role":"解题依据","why":"结果成立必有其必要条件，必要条件不成立可推出结果不成立。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-8b7425ce10958bbe":[["江苏 2024 A类 行测#91"]]}};
